mapper.insert:
insert into bss_inventory_detail ( id, pallet_no, barcode, wh_cd, loc_cd, classification, item_code, item_name, qty, allocation_qty, status, last_status, remarks, delete_flg,
) values ( #{id}, #{palletNo}, #{barcode}, #{whCd}, #{locCd}, #{classification}, #{itemCode}, #{itemName,jdbcType=VARCHAR}, #{qty}, #{allocationQty,jdbcType=NUMERIC}, #{status}, #{lastStatus}, #{remarks,jdbcType=VARCHAR}, #{deleteFlg},
)

insert into bss_inventory_history ( id, wh_cd, zone_cd, loc_cd, item_code, item_name, uom, pallet_no, status, storage_type, storage_qty, used_qty, lost_damaged_qty, transfer_datetime, transfer_request_no, request_datetime, requester, io_datetime, io_operator, storage_period,
) values ( #{id}, #{whCd}, #{zoneCd}, #{locCd}, #{itemCode}, #{itemName}, #{uom,jdbcType=VARCHAR}, #{palletNo}, #{status}, #{storageType,jdbcType=VARCHAR}, #{storageQty}, #{usedQty,jdbcType=NUMERIC}, #{lostDamagedQty,jdbcType=NUMERIC}, #{transferDatetime,jdbcType=VARCHAR}, #{transferRequestNo,jdbcType=VARCHAR}, #{requestDatetime,jdbcType=VARCHAR}, #{requester,jdbcType=VARCHAR}, #{ioDatetime,jdbcType=VARCHAR}, #{ioOperator,jdbcType=VARCHAR}, #{storagePeriod,jdbcType=VARCHAR},
)

mapper.select:
select zone_cd
from mast_location
where wh_cd = #{whCd}
  and loc_cd = #{locCd}
  and delete_flg = '0'
limit 1
